/bin/zsh -lc "cat > index.html <<'EOF'
<"'!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Local JPEG Compressor</title>
  <style>
    :root {
      color-scheme: light dark;
      --paper: #f6f7f9;
      --surface: #ffffff;
      --ink: #191c25;
      --muted: #565e70;
      --line: #dce0e8;
      --preview: #eef0f5;
      --accent: #5440c9;
      --lobe-color-primary: var(--accent);
    }

    @media (prefers-color-scheme: dark) {
      :root {
        --paper: #15161d;
        --surface: #1d1f28;
        --ink: #f2f2f8;
        --muted: #b1b6c7;
        --line: #363948;
        --preview: #181a23;
        --accent: #a99bff;
      }
    }

    *, *::before, *::after { box-sizing: border-box; }
    [hidden] { display: none !important; }

    body {
      margin: 0;
      padding: clamp(24px, 6vw, 72px) clamp(16px, 4vw, 40px);
      background: var(--paper);
      color: var(--ink);
      font: 15px/1.5 system-ui, sans-serif;
    }

    main { max-width: 1024px; margin-inline: auto; }
    header { margin-bottom: 30px; }
    h1, h2, p, dl, dd { margin: 0; }
    h1 { font-size: clamp(30px, 5vw, 48px); letter-spacing: -.055em; line-height: 1.12; }
    h2 { font-size: 15px; font-weight: 680; }
    header p { margin-top: 10px; color: var(--muted); }

    .workspace {
      display: grid;
      grid-template-columns: minmax(240px, 300px) minmax(0, 1fr);
      background: var(--surface);
      border: 1px solid var(--line);
      border-radius: 18px;
    }

    .controls, .results { min-width: 0; padding: clamp(16px, 3vw, 26px); }
    .controls { display: grid; align-content: start; gap: 24px; border-right: 1px solid var(--line); }
    .control-group, .file-controls { display: grid; gap: 8px; min-width: 0; }
    .file-controls ryugi-button { justify-self: start; }
    .file-name, .hint { font-size: 13px; color: var(--muted); overflow-wrap: anywhere; }
    .label-row { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
    .unit { color: var(--muted); font-size: 12px; }
    ryugi-slider-input { display: block; width: 100%; }

    .results { display: grid; gap: 16px; align-content: start; }
    .preview {
      min-height: clamp(230px, 39vw, 400px);
      padding: 16px;
      display: grid;
      place-items: center;
      background-color: var(--preview);
      background-image: radial-gradient(var(--line) 1px, transparent 1px);
      background-size: 16px 16px;
      border: 1px solid var(--line);
      border-radius: 12px;
    }

    .empty { display: grid; justify-items: center; gap: 12px; text-align: center; color: var(--muted); }
    .empty ryugi-icon { color: var(--accent); }
    .preview img { display: block; max-width: 100%; max-height: 65vh; object-fit: contain; }
    .summary { display: flex; justify-content: space-between; align-items: end; flex-wrap: wrap; gap: 16px 24px; }
    dl { display: flex; gap: clamp(20px, 4vw, 36px); }
    dt { color: var(--muted); font-size: 12px; }
    dd { font-size: 19px; font-weight: 680; font-variant-numeric: tabular-nums; }
    .status { min-height: 1.5em; color: var(--muted); font-size: 13px; }
    .status:empty { display: none; }

    @media (max-width: 650px) {
      .workspace { grid-template-columns: minmax(0, 1fr); }
      .controls { border-right: 0; border-bottom: 1px solid var(--line); }
    }
  </style>
</head>
<body>
  <main>
    <header>
      <h1>JPEG compressor</h1>
      <p>Resize and compress an image in your browser.</p>
    </header>

    <div class="workspace">
      <section class="controls" aria-label="Compression settings">
        <div class="file-controls">
          <h2>Source image</h2>
          <input id="source-file" type="file" accept="image/*" hidden>
          <ryugi-button id="choose-file" variant="outlined" icon="upload">Choose image</ryugi-button>
          <p id="file-name" class="file-name" hidden></p>
        </div>

        <div class="control-group">
          <div class="label-row">
            <h2 id="quality-label">JPEG quality</h2>
            <span class="unit">%</span>
          </div>
          <ryugi-slider-input id="quality" aria-labelledby="quality-label" value="80" min="1" max="100" step="1"></ryugi-slider-input>
        </div>

        <div class="control-group">
          <div class="label-row">
            <h2 id="width-label">Max width</h2>
            <span class="unit">px</span>
          </div>
          <ryugi-slider-input id="max-width" aria-labelledby="width-label" value="1920" min="1" max="8192" step="1"></ryugi-slider-input>
          <p class="hint">Keeps the aspect ratio and only shrinks larger images.</p>
        </div>
      </section>

      <section class="results" aria-labelledby="preview-title">
        <h2 id="preview-title">Compressed preview</h2>
        <div class="preview" id="preview">
          <div class="empty" id="preview-placeholder">
            <ryugi-icon name="image" size="36" stroke-width="1.5" aria-hidden="true"></ryugi-icon>
            <p id="placeholder-text">Choose a local image to preview it here.</p>
          </div>
          <img id="preview-image" alt="Compressed JPEG preview" hidden>
        </div>
        <div class="summary">
          <dl aria-label="File sizes">
            <div><dt>Original</dt><dd id="original-size">—</dd></div>
            <div><dt>JPEG</dt><dd id="jpeg-size">—</dd></div>
          </dl>
          <ryugi-button id="download" variant="filled" icon="download" disabled>Download JPEG</ryugi-button>
        </div>
        <p class="status" id="status" role="status"></p>
      </section>
    </div>
  </main>

  <script>
    document.addEventListener('"'ryugi-ui:ready', () => {
      const byId = (id) => document.getElementById(id);
      const fileInput = byId('source-file');
      const quality = byId('quality');
      const maxWidth = byId('max-width');
      const fileName = byId('file-name');
      const originalSize = byId('original-size');
      const jpegSize = byId('jpeg-size');
      const preview = byId('preview-image');
      const placeholder = byId('preview-placeholder');
      const placeholderText = byId('placeholder-text');
      const status = byId('status');
      const download = byId('download');

      let source = null;
      let resultURL = null;
      let downloadName = 'compressed.jpg';
      let fileRevision = 0;
      let renderRevision = 0;
      let renderTimer;

      function formatSize(bytes) {
        const units = ['B', 'KiB', 'MiB', 'GiB'];
        let unit = 0;
        let amount = bytes;

        while (amount >= 1024 && unit < units.length - 1) {
          amount /= 1024;
          unit += 1;
        }

        const formatted = amount.toLocaleString(undefined, {
          maximumFractionDigits: unit === 0 ? 0 : 2,
        });
        return formatted + ' ' + units[unit];
      }

      function clearResult(message) {
        if (resultURL) URL.revokeObjectURL(resultURL);
        resultURL = null;
        preview.removeAttribute('src');
        preview.hidden = true;
        placeholder.hidden = false;
        placeholderText.textContent = message;
        jpegSize.textContent = '—';
        download.setAttribute('disabled', '');
      }

      async function compress(revision) {
        const canvas = document.createElement('canvas');
        try {
          const widthLimit = Number(maxWidth.value) || 1920;
          const jpegQuality = Number(quality.value) || 80;
          const width = Math.min(source.naturalWidth, widthLimit);
          const height = Math.max(1, Math.round(source.naturalHeight * width / source.naturalWidth));
          canvas.width = width;
          canvas.height = height;

          const context = canvas.getContext('2d', { alpha: false });
          if ("'!context) throw new Error('"'Canvas unavailable');
          context.fillStyle = '#fff';
          context.fillRect(0, 0, width, height);
          context.imageSmoothingQuality = 'high';
          context.drawImage(source, 0, 0, width, height);

          const blob = await new Promise((resolve) => {
            canvas.toBlob(resolve, 'image/jpeg', jpegQuality / 100);
          });
          if (revision "'!== renderRevision) return;
          if (!blob || blob.type !== '"'image/jpeg') throw new Error('JPEG encoding failed');

          const nextURL = URL.createObjectURL(blob);
          if (resultURL) URL.revokeObjectURL(resultURL);
          resultURL = nextURL;
          preview.src = resultURL;
          preview.hidden = false;
          placeholder.hidden = true;
          jpegSize.textContent = formatSize(blob.size);
          status.textContent = width.toLocaleString() + ' × ' + height.toLocaleString() + ' px';
          download.removeAttribute('disabled');
        } catch {
          if (revision "'!== renderRevision) return;
          clearResult('"'Preview unavailable.');
          status.textContent = 'Could not create the JPEG. Try a smaller max width.';
        } finally {
          canvas.width = 0;
          canvas.height = 0;
        }
      }

      function queueCompression(delay = 120) {
        if ("'!source) return;
        clearTimeout(renderTimer);
        const revision = ++renderRevision;
        placeholderText.textContent = '"'Compressing image…';
        status.textContent = 'Compressing image…';
        download.setAttribute('disabled', '');
        renderTimer = setTimeout(() => compress(revision), delay);
      }

      async function loadFile(file) {
        const revision = ++fileRevision;
        ++renderRevision;
        clearTimeout(renderTimer);
        source = null;
        clearResult('Opening image…');
        fileName.textContent = file.name;
        fileName.hidden = false;
        originalSize.textContent = formatSize(file.size);
        status.textContent = '';
        downloadName = (file.name.replace(/\\.["'^.]+$/, '"'') || 'image') + '-compressed.jpg';

        const image = new Image();
        const url = URL.createObjectURL(file);
        try {
          await new Promise((resolve, reject) => {
            image.onload = resolve;
            image.onerror = reject;
            image.src = url;
          });
          if (revision "'!== fileRevision) return;
          source = image;
          queueCompression(0);
        } catch {
          if (revision !== fileRevision) return;
          clearResult('"'Preview unavailable.');
          status.textContent = 'Could not open this image. Choose an image your browser supports.';
        } finally {
          URL.revokeObjectURL(url);
        }
      }

      byId('choose-file').addEventListener('click', () => fileInput.click());
      fileInput.addEventListener('change', () => {
        const file = fileInput.files[0];
        if (file) loadFile(file);
        fileInput.value = '';
      });

      document.addEventListener('ryugi-change', (event) => {
        if (event.target === quality || event.target === maxWidth) queueCompression();
      });

      download.addEventListener('click', () => {
        if ("'!resultURL || download.hasAttribute('"'disabled')) return;
        const link = document.createElement('a');
        link.href = resultURL;
        link.download = downloadName;
        document.body.append(link);
        link.click();
        link.remove();
      });
    }, { once: true });
  </script>
</body>
</html>
